def transitive_closure(vertices, edges):
    """
    Computes the transitive closure of a directed graph.

    :param vertices: Number of vertices in the graph.
    :param edges: List of pairs (source, target) representing directed edges in the graph.
    :return: A 2D list representing the transitive closure of the graph.
    """
    closure = [[0] * vertices for _ in range(vertices)]

    # Initialize the adjacency matrix representation of the graph
    for i in range(vertices):
        closure[i][i] = 1  # Every vertex is reachable from itself

    for u, v in edges:
        closure[u][v] = 1

    # Use the Floyd-Warshall algorithm to compute the transitive closure
    for k in range(vertices):
        for i in range(vertices):
            for j in range(vertices):
                if closure[i][k] and closure[k][j]:
                    closure[i][j] = 1

    return closure

def optimized_exchange_sort(arr):
    """
    Sorts a list of integers using an optimized version of the Exchange Sort.

    This function handles various edge cases efficiently and reduces unnecessary swaps.
    """
    n = len(arr)
    if n <= 1:
        # No need to sort if list is empty or has one element.
        return arr

    for i in range(n-1):
        swapped = False
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                # Swap the elements if they are in the wrong order
                arr[i], arr[j] = arr[j], arr[i]
                swapped = True
        if not swapped:
            # If no swaps occurred in the inner loop, array is sorted
            break

    return arr

def quick_sort(arr):
    """
    Function that implements the QuickSort algorithm to sort a given list of integers in ascending order.
    """
    if len(arr) <= 1:
        return arr
    else:
        pivot = arr[len(arr) // 2]
        left = [x for x in arr if x < pivot]
        middle = [x for x in arr if x == pivot]
        right = [x for x in arr if x > pivot]
        return quick_sort(left) + middle + quick_sort(right)

