def shortest_path_with_constraints(roads, source, destination, blocked):
    # Create an adjacency list for graph representation
    graph = {}
    for u, v, t in roads:
        if (u, v) in blocked or (v, u) in blocked:
            continue
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, t))
        graph[v].append((u, t))

    # Use a priority queue to implement Dijkstra's algorithm
    pq = [(0, source)]  # (distance, node)
    distances = {source: 0}

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_node == destination:
            return current_distance

        if current_distance > distances.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            if distance < distances.get(neighbor, float('inf')):
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return -1

def count_unique_balanced_substrings(s):
    """
    Counts the number of unique balanced substrings in a string consisting of '0's and '1's.
    A balanced substring has an equal number of '0's and '1's.
    """
    n = len(s)
    count = 0

    # Iterate over all possible substrings
    for i in range(n):
        zero_count = 0
        one_count = 0
        for j in range(i, n):
            if s[j] == '0':
                zero_count += 1
            else:
                one_count += 1

            # If the counts of '0' and '1' are equal, we found a balanced substring
            if zero_count == one_count:
                count += 1

    return count

